(()=>{const d=document,b=d.body,q=s=>d.querySelector(s),qa=s=>[...d.querySelectorAll(s)],store={theme:"portfolio-theme",contact:"portfolio-contact-draft"},projects={ums:{title:"University Management System",description:"A Java application connected with MySQL using JDBC. It manages core university workflows such as student registration, course assignment, and data retrieval while applying OOP principles for maintainable code.",meta:["Java","MySQL","JDBC","CRUD Flow"]},ttt:{title:"Tic Tac Toe Game",description:"A browser game built with HTML, CSS, and JavaScript. It handles turn switching, win and draw conditions, dynamic DOM updates, and a responsive interface.",meta:["HTML","CSS","JavaScript","DOM"]}},applyTheme=t=>{b.className=t;localStorage.setItem(store.theme,t);q("#themeToggle").textContent=t==="dark"?"🌙":"☀️"},toggleTheme=()=>applyTheme(b.classList.contains("dark")?"light":"dark"),setYear=()=>q("#year").textContent=new Date().getFullYear(),toggleNav=()=>{const links=q("#navLinks"),open=links.classList.toggle("open");q("#navToggle").setAttribute("aria-expanded",String(open))},closeNav=()=>{q("#navLinks").classList.remove("open");q("#navToggle").setAttribute("aria-expanded","false")},animateSkills=()=>{const io=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){const skill=entry.target,l=skill.dataset.level;skill.querySelector(".bar span").style.width=l+"%";io.unobserve(skill)}})},{threshold:.35});qa(".skill").forEach(s=>io.observe(s))},openModal=id=>{const p=projects[id];if(!p)return;q("#modalTitle").textContent=p.title;q("#modalDescription").textContent=p.description;q("#modalMeta").innerHTML=p.meta.map(v=>`<span>${v}</span>`).join("");const m=q("#projectModal");m.classList.add("open");m.setAttribute("aria-hidden","false")},closeModal=()=>{const m=q("#projectModal");m.classList.remove("open");m.setAttribute("aria-hidden","true")},validateEmail=e=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e),setError=(field,msg)=>field.parentElement.querySelector(".error").textContent=msg,saveDraft=()=>{const data={name:q("#name").value.trim(),email:q("#email").value.trim(),message:q("#message").value.trim()};localStorage.setItem(store.contact,JSON.stringify(data))},loadDraft=()=>{try{const raw=localStorage.getItem(store.contact);if(!raw)return;const data=JSON.parse(raw);["name","email","message"].forEach(k=>{if(data[k])q("#"+k).value=data[k]})}catch(e){console.warn("Draft load skipped",e)}},handleSubmit=e=>{e.preventDefault();const name=q("#name"),email=q("#email"),message=q("#message"),status=q("#formStatus");[name,email,message].forEach(f=>setError(f,""));status.textContent="";let ok=!0;if(name.value.trim().length<2){setError(name,"Please enter at least 2 characters.");ok=!1}if(!validateEmail(email.value.trim())){setError(email,"Please enter a valid email address.");ok=!1}if(message.value.trim().length<10){setError(message,"Please enter at least 10 characters.");ok=!1}if(!ok){status.textContent="Please fix the highlighted fields.";status.style.color="#ef4444";return}saveDraft();status.textContent="Message validated and saved locally.";status.style.color="#22c55e"},bind=()=>{q("#themeToggle").addEventListener("click",toggleTheme);q("#navToggle").addEventListener("click",toggleNav);qa('.nav-links a').forEach(a=>a.addEventListener("click",closeNav));qa(".project-btn").forEach(b=>b.addEventListener("click",()=>openModal(b.dataset.project)));q("#modalClose").addEventListener("click",closeModal);q("#projectModal").addEventListener("click",e=>{if(e.target.dataset.close==="modal")closeModal()});d.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});q("#contactForm").addEventListener("submit",handleSubmit);["name","email","message"].forEach(id=>q("#"+id).addEventListener("input",saveDraft))},init=()=>{applyTheme(localStorage.getItem(store.theme)||"dark");setYear();loadDraft();animateSkills();bind()};init()})();